/** Read-only typed adoption plan. Source cells remain usable until the arm journal owns the complete transfer. */
public final class NativeGearLandingPlan {
    private final List<NativeGearSnapshot.Cell> sources,targets;
    private final CompoundTag rootAfter;
    private final GearTopology.FootKind kind;
    private final List<GearTopology.Cell> feet;
    private final Set<GearTopology.Cell> wheelRoots;
    private NativeGearLandingPlan(List<NativeGearSnapshot.Cell> sources,List<NativeGearSnapshot.Cell> targets,CompoundTag rootAfter,GearTopology.FootKind kind,List<GearTopology.Cell> feet,Set<GearTopology.Cell> roots){this.sources=List.copyOf(sources);this.targets=List.copyOf(targets);this.rootAfter=rootAfter.copy();this.kind=kind;this.feet=List.copyOf(feet);wheelRoots=Set.copyOf(roots);}
    public List<NativeGearSnapshot.Cell> sources(){return sources;}public List<NativeGearSnapshot.Cell> targets(){return targets;}public CompoundTag rootAfter(){return rootAfter.copy();}public GearTopology.FootKind kind(){return kind;}public List<GearTopology.Cell> feet(){return feet;}public Set<GearTopology.Cell> wheelRoots(){return wheelRoots;}
    private static void loaded(ServerLevel world,BlockPos at){if(!NativeGearFormation.loaded(world,at))throw new IllegalArgumentException("Load the active foot group and its boundary first");}
    private static Direction direction(NativeGearPayload.Transform transform,Direction face){var vector=transform.vector(face.getStepX(),face.getStepY(),face.getStepZ());var mapped=Direction.getNearest(vector.x,vector.y,vector.z);if(vector.distanceToSqr(Vec3.atLowerCornerOf(mapped.getNormal()))>1e-12)throw new IllegalArgumentException("Landing socket is not grid aligned");return mapped;}
    private static BlockPos point(BlockPos root,NativeGearPayload.Transform transform,BlockPos at){var local=at.subtract(root);var center=transform.point(local.getX()+.5,local.getY()+.5,local.getZ()+.5);double x=center.x-.5,y=center.y-.5,z=center.z-.5;if(Math.abs(x-Math.rint(x))+Math.abs(y-Math.rint(y))+Math.abs(z-Math.rint(z))>1e-8)throw new IllegalArgumentException("Landing socket is not on the native grid");return root.offset((int)Math.rint(x),(int)Math.rint(y),(int)Math.rint(z));}
    private static Direction facing(Direction oldFrame,Direction newFrame,Direction local,NativeGearPayload.Transform inverse){var world=NativeGearOrientation.vector(oldFrame,local.getStepX(),local.getStepY(),local.getStepZ());var mapped=inverse.vector(world.x,world.y,world.z);var inPlane=NativeGearOrientation.inverse(newFrame,new BlockPos((int)Math.rint(mapped.x),(int)Math.rint(mapped.y),(int)Math.rint(mapped.z)));var result=Direction.getNearest(inPlane.getX(),inPlane.getY(),inPlane.getZ());if(result.getAxis()==Direction.Axis.Y)throw new IllegalArgumentException("Landing foot facing leaves its component plane");return result;}
    private static long packed(BlockPos pos){return ((long)pos.getX()&67108863L)<<38|((long)pos.getY()&4095L)<<26|((long)pos.getZ()&67108863L);}
    private static NativeGearSnapshot.Cell mapped(NativeGearEntity owner,NativeGearSnapshot.Cell source,NativeGearPayload.Transform inverse,HolderLookup.Provider registries){
        if(source.section||!(source.state.getBlock() instanceof NativeGearBlock block)||!block.definition().foot())throw new IllegalArgumentException("Landing source is not a typed foot");var tile=(NativeGearEntity)NativeGearSnapshot.stage(registries,source,true);if(tile.inert()||tile.owner()!=null||tile.assembly()!=null||tile.ownsCaptured()||source.state.getValue(NativeGearBlock.ASSEMBLED))throw new IllegalArgumentException("Landing source already has an owner");var definition=tile.definition();var target=point(owner.getBlockPos(),inverse,source.pos);var state=source.state;var data=source.tile();var mount=direction(inverse,tile.mount());var frame=direction(inverse,tile.componentFrame());if(definition==NativeGearDefinition.LARGE_WHEEL&&(frame!=owner.mount()||mount!=owner.mount()))throw new IllegalArgumentException("Large Wheel component frame leaves the socket plane");if(mount==owner.mount()){state=state.setValue(NativeGearBlock.FACING,facing(tile.componentFrame(),frame,state.getValue(NativeGearBlock.FACING),inverse));if(data.contains("GearDirection",Tag.TAG_STRING))data.putString("GearDirection",facing(tile.mount(),mount,Direction.valueOf(data.getString("GearDirection")),inverse).name());for(String key:List.of("GearFootFacing","ArmFootFacing"))if(data.contains(key,Tag.TAG_INT))data.putInt(key,facing(tile.mount(),mount,Direction.from2DDataValue(data.getInt(key)),inverse).get2DDataValue());}data.putString("ArmMountDirection",owner.mount().name());if(definition!=NativeGearDefinition.LARGE_WHEEL||owner.mount()!=Direction.DOWN)data.putString("ArmFootComponentFrame",owner.mount().name());else data.remove("ArmFootComponentFrame");data.putBoolean("GearController",false);data.putBoolean("GearOperational",false);data.putLong("GearOwnerOffset",packed(owner.getBlockPos().subtract(target)));data.putString("GearError","");data.putInt("x",target.getX());data.putInt("y",target.getY());data.putInt("z",target.getZ());return new NativeGearSnapshot.Cell(target,state.setValue(NativeGearBlock.ASSEMBLED,true),data);
    }
    /** Structural replay validation uses the immutable before image, never the possibly half-published world. */
    static NativeGearLandingPlan validate(NativeGearEntity owner,List<NativeGearSnapshot.Cell> before,List<NativeGearSnapshot.Cell> after,CompoundTag action,HolderLookup.Provider registries){
        if(!action.getAllKeys().equals(Set.of("Type","RootAfter"))||!action.getString("Type").equals("ADOPT")||!action.contains("RootAfter",Tag.TAG_COMPOUND)||owner.definition().kind!=NativeGearDefinition.Kind.ROTATING||owner.progress()!=0||owner.assembly()==null||owner.assembly().kind()!=GearTopology.FootKind.NONE||owner.payload()!=null||owner.hasStoredSections()||owner.settings().startAngle()!=0||owner.settings().activeAngle()!=90)throw new IllegalArgumentException("Malformed typed landing transition");var endpoint=NativeGearPayload.relativeTransform(owner,0,NativeGearPayload.frame(owner,1));var inverse=endpoint.inverse();var root=owner.getBlockPos();int height=owner.assembly().columnHeight();var sources=new LinkedHashMap<BlockPos,NativeGearSnapshot.Cell>();var expected=new LinkedHashMap<BlockPos,NativeGearSnapshot.Cell>();var offsets=new ArrayList<GearTopology.Cell>();var roots=new HashSet<GearTopology.Cell>();var identities=new HashSet<UUID>();NativeGearDefinition definition=null;Direction orientation=null;
        for(var cell:before){if(cell.state.isAir()){if(cell.tile()!=null||cell.section)throw new IllegalArgumentException("Landing air before image has ownership");continue;}var target=mapped(owner,cell,inverse,registries);var tile=(NativeGearEntity)NativeGearSnapshot.stage(registries,cell,true);if(!identities.add(tile.identity()))throw new IllegalArgumentException("Duplicate landing foot identity");if(definition==null)definition=tile.definition();else if(definition!=tile.definition())throw new IllegalArgumentException("Mixed landing source families");var local=NativeGearOrientation.inverse(owner.mount(),target.pos.subtract(root));if(local.getY()!=-height)throw new IllegalArgumentException("Landing target outside construction plane");var foot=new GearTopology.Cell(local.getX(),local.getY(),local.getZ());offsets.add(foot);if(definition==NativeGearDefinition.LARGE_WHEEL&&target.state.getValue(NativeGearBlock.PART)==0)roots.add(foot);var facing=target.state.getValue(NativeGearBlock.FACING);if(orientation==null)orientation=facing;else if(definition.kind!=NativeGearDefinition.Kind.PLATE&&orientation!=facing)throw new IllegalArgumentException("Mixed landing orientations");if(sources.put(cell.pos,cell)!=null||expected.put(target.pos,target)!=null)throw new IllegalArgumentException("Landing mapping duplicate");}
        if(definition==null||sources.size()>64||definition.kind==NativeGearDefinition.Kind.WHEEL&&definition.size!=owner.definition().size)throw new IllegalArgumentException("Landing source count/size");var first=point(root,endpoint,root.offset(NativeGearOrientation.vector(owner.mount(),new BlockPos(0,-height,0))));if(!sources.containsKey(first))throw new IllegalArgumentException("Landing socket has no source foot");var normal=direction(endpoint,owner.mount());var seen=new HashSet<BlockPos>();var queue=new ArrayDeque<BlockPos>();queue.add(first);while(!queue.isEmpty()){var at=queue.removeFirst();if(!seen.add(at))continue;for(var side:Direction.values())if(side.getAxis()!=normal.getAxis()&&sources.containsKey(at.relative(side)))queue.add(at.relative(side));}if(seen.size()!=sources.size())throw new IllegalArgumentException("Disconnected landing source group");
        var topology=GearTopology.validate(height,definition.footKind(),offsets);if(!topology.isValid())throw new IllegalArgumentException(topology.error());for(var column:owner.columns())if(!expected.containsKey(root.offset(column).relative(owner.mount(),height)))throw new IllegalArgumentException("Landing support correspondence");if(definition==NativeGearDefinition.LARGE_WHEEL){for(var cell:sources.values()){var tile=(NativeGearEntity)NativeGearSnapshot.stage(registries,cell,true);if(tile.componentFrame()!=normal)throw new IllegalArgumentException("Landing native component frame");var anchor=NativeGearComponents.root(cell.pos,cell.state,tile.componentFrame());var cells=NativeGearComponents.cells(anchor,tile.componentFrame(),cell.state.getValue(NativeGearBlock.FACING));for(int n=0;n<4;n++){var part=sources.get(cells.get(n));if(part==null||part.state.getBlock()!=cell.state.getBlock()||part.state.getValue(NativeGearBlock.PART)!=n||part.state.getValue(NativeGearBlock.FACING)!=cell.state.getValue(NativeGearBlock.FACING))throw new IllegalArgumentException("Incomplete landing source component");}}for(var cell:expected.values()){var anchor=NativeGearComponents.root(cell.pos,cell.state,owner.mount());var cells=NativeGearComponents.cells(anchor,owner.mount(),cell.state.getValue(NativeGearBlock.FACING));for(int n=0;n<4;n++){var part=expected.get(cells.get(n));if(part==null||part.state.getBlock()!=cell.state.getBlock()||part.state.getValue(NativeGearBlock.PART)!=n||part.state.getValue(NativeGearBlock.FACING)!=cell.state.getValue(NativeGearBlock.FACING))throw new IllegalArgumentException("Incomplete landing target component");}}}
        var footprint=new HashSet<BlockPos>(sources.keySet());footprint.addAll(expected.keySet());if(before.size()!=footprint.size()||after.size()!=footprint.size())throw new IllegalArgumentException("Landing transfer footprint");for(var cell:before)if(!footprint.contains(cell.pos))throw new IllegalArgumentException("Unrelated landing before cell");for(var cell:after){var target=expected.get(cell.pos);if(target==null){if(!sources.containsKey(cell.pos)||!cell.state.isAir()||cell.tile()!=null||cell.section)throw new IllegalArgumentException("Landing source retirement");}else if(cell.state!=target.state||cell.section||!NativeGearSnapshot.same(cell.tile(),target.tile()))throw new IllegalArgumentException("Landing target data changed");}var rootAfter=owner.landingAfter(definition.footKind(),topology.assembly().feet(),orientation.get2DDataValue(),roots,registries);if(!NativeGearSnapshot.same(rootAfter,action.getCompound("RootAfter")))throw new IllegalArgumentException("Landing root after image changed");return new NativeGearLandingPlan(new ArrayList<>(sources.values()),new ArrayList<>(expected.values()),rootAfter,definition.footKind(),topology.assembly().feet(),roots);
    }
    public static NativeGearLandingPlan capture(NativeGearEntity owner){
        if(!(owner.getLevel() instanceof ServerLevel world)||!owner.authority()||!owner.controller()||owner.definition().kind!=NativeGearDefinition.Kind.ROTATING||owner.progress()!=0||owner.assembly().kind()!=GearTopology.FootKind.NONE||owner.payload()!=null||owner.hasStoredSections())return null;
        int height=owner.assembly().columnHeight();var root=owner.getBlockPos();var endpoint=NativeGearPayload.relativeTransform(owner,0,NativeGearPayload.frame(owner,1));var inverse=endpoint.inverse();var home=root.offset(NativeGearOrientation.vector(owner.mount(),new BlockPos(0,-height,0)));final BlockPos first;try{first=point(root,endpoint,home);}catch(IllegalArgumentException fractional){return null;}loaded(world,first);var seed=NativeGearFormation.at(world,first);if(seed==null||!seed.definition().foot())return null;if(owner.settings().startAngle()!=0||owner.settings().activeAngle()!=90)throw new IllegalArgumentException("Use Start 0 and End 90 before attaching landing gear");var definition=seed.definition();if(definition.kind==NativeGearDefinition.Kind.WHEEL&&definition.size!=owner.definition().size)throw new IllegalArgumentException("Wheel and arm sizes must match");var normal=direction(endpoint,owner.mount());var actor=owner.actor();if(actor==null)throw new IllegalArgumentException("The arm owner must return before attaching feet");
        var pending=new ArrayDeque<BlockPos>();var visited=new LinkedHashSet<BlockPos>();var sources=new ArrayList<NativeGearSnapshot.Cell>();var targets=new LinkedHashMap<BlockPos,NativeGearSnapshot.Cell>();var offsets=new ArrayList<GearTopology.Cell>();var roots=new HashSet<GearTopology.Cell>();pending.add(first);Direction targetFacing=null;long bytes=0;
        while(!pending.isEmpty()){
            var at=pending.removeFirst();if(!visited.add(at))continue;if(visited.size()>GearTopology.MAX_FEET)throw new IllegalArgumentException("A landing group may contain at most 64 feet");loaded(world,at);var tile=NativeGearFormation.at(world,at);if(tile==null||tile.definition()!=definition||tile.inert()||tile.owner()!=null||tile.assembly()!=null||tile.ownsCaptured()||tile.getBlockState().getValue(NativeGearBlock.ASSEMBLED))throw new IllegalArgumentException("Use one unowned landing-foot type");if(!NativeGearComponents.intact(world,at))throw new IllegalArgumentException("Keep every Large Wheel cell intact");if(!world.mayInteract(actor,at)||!actor.mayUseItemAt(at,normal,actor.getMainHandItem()))throw new IllegalArgumentException("You cannot attach these feet");if(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.level.BlockEvent.BreakEvent(world,at,tile.getBlockState(),actor)).isCanceled())throw new IllegalArgumentException("A protection rule prevented attaching the feet");
            var source=new NativeGearSnapshot.Cell(at,tile.getBlockState(),tile.saveWithFullMetadata(world.registryAccess()));NativeGearSnapshot.stage(world,source,true);var target=point(root,inverse,at);var local=NativeGearOrientation.inverse(owner.mount(),target.subtract(root));if(local.getY()!=-height||Math.abs(local.getX())>64||Math.abs(local.getZ())>64)throw new IllegalArgumentException("The foot group leaves the construction plane");var state=tile.getBlockState();var data=source.tile();var mappedMount=direction(inverse,tile.mount());var mappedFrame=direction(inverse,tile.componentFrame());if(definition==NativeGearDefinition.LARGE_WHEEL&&(tile.componentFrame()!=normal||mappedFrame!=owner.mount()||mappedMount!=owner.mount()))throw new IllegalArgumentException("Place the complete Large Wheel in the active socket plane");
            if(mappedMount==owner.mount()){
                state=state.setValue(NativeGearBlock.FACING,facing(tile.componentFrame(),mappedFrame,state.getValue(NativeGearBlock.FACING),inverse));
                if(data.contains("GearDirection",Tag.TAG_STRING)){var old=Direction.valueOf(data.getString("GearDirection"));data.putString("GearDirection",facing(tile.mount(),mappedMount,old,inverse).name());}
                for(String key:List.of("GearFootFacing","ArmFootFacing"))if(data.contains(key,Tag.TAG_INT))data.putInt(key,facing(tile.mount(),mappedMount,Direction.from2DDataValue(data.getInt(key)),inverse).get2DDataValue());
            }
            var placedFacing=state.getValue(NativeGearBlock.FACING);if(targetFacing==null)targetFacing=placedFacing;else if(definition.kind!=NativeGearDefinition.Kind.PLATE&&targetFacing!=placedFacing)throw new IllegalArgumentException("Align connected skis and wheels");data.putString("ArmMountDirection",owner.mount().name());if(definition!=NativeGearDefinition.LARGE_WHEEL||owner.mount()!=Direction.DOWN)data.putString("ArmFootComponentFrame",owner.mount().name());else data.remove("ArmFootComponentFrame");data.putBoolean("GearController",false);data.putBoolean("GearOperational",false);data.putLong("GearOwnerOffset",packed(root.subtract(target)));data.putString("GearError","");data.putInt("x",target.getX());data.putInt("y",target.getY());data.putInt("z",target.getZ());state=state.setValue(NativeGearBlock.ASSEMBLED,true);var after=new NativeGearSnapshot.Cell(target,state,data);NativeGearSnapshot.stage(world,after,true);if(targets.put(target,after)!=null)throw new IllegalArgumentException("Landing mapping overlaps itself");var offset=new GearTopology.Cell(local.getX(),local.getY(),local.getZ());offsets.add(offset);if(definition==NativeGearDefinition.LARGE_WHEEL&&state.getValue(NativeGearBlock.PART)==0)roots.add(offset);sources.add(source);bytes+=source.bytes()+after.bytes();if(bytes>NativeGearSnapshot.MAX_BYTES)throw new IllegalArgumentException("Landing group snapshot exceeds its bounded budget");
            for(var side:Direction.values())if(side.getAxis()!=normal.getAxis()){var next=at.relative(side);loaded(world,next);var neighbor=NativeGearFormation.at(world,next);if(neighbor!=null&&neighbor.definition().foot())pending.add(next);}
        }
        var topology=GearTopology.validate(height,definition.footKind(),offsets);if(!topology.isValid())throw new IllegalArgumentException(topology.error());for(var column:owner.columns())if(!targets.containsKey(root.offset(column).relative(owner.mount(),height)))throw new IllegalArgumentException("Every joined column needs a connected landing foot");
        for(var target:targets.values()){loaded(world,target.pos);if(!visited.contains(target.pos)&&(!world.getBlockState(target.pos).isAir()||world.getBlockEntity(target.pos)!=null))throw new IllegalArgumentException("Clear every landing construction cell");if(!world.mayInteract(actor,target.pos)||!actor.mayUseItemAt(target.pos,owner.mount(),actor.getMainHandItem()))throw new IllegalArgumentException("You cannot install the landing construction cells");var above=target.pos.relative(owner.mount().getOpposite());loaded(world,above);var strut=NativeGearFormation.at(world,above);if(strut!=null&&strut.definition().arm()&&!owner.members().contains(above))throw new IllegalArgumentException("The foot group touches another arm");}
        if(definition==NativeGearDefinition.LARGE_WHEEL)for(var target:targets.values()){var anchor=NativeGearComponents.root(target.pos,target.state,owner.mount());var cells=NativeGearComponents.cells(anchor,owner.mount(),target.state.getValue(NativeGearBlock.FACING));for(int n=0;n<4;n++){var member=targets.get(cells.get(n));if(member==null||member.state.getBlock()!=target.state.getBlock()||member.state.getValue(NativeGearBlock.PART)!=n||member.state.getValue(NativeGearBlock.FACING)!=target.state.getValue(NativeGearBlock.FACING))throw new IllegalArgumentException("The construction plane cannot retain the complete Large Wheel");}for(var column:owner.columns()){var at=root.offset(column).relative(owner.mount(),height);var member=targets.get(at);if(member==null||member.state.getValue(NativeGearBlock.PART)!=0||member.state.getValue(NativeGearBlock.FACING)!=world.getBlockState(root.offset(column)).getValue(NativeGearBlock.FACING))throw new IllegalArgumentException("Align every Large Wheel anchor with its Large arm");}}
        var after=owner.landingAfter(definition.footKind(),topology.assembly().feet(),targetFacing.get2DDataValue(),roots,world.registryAccess());var preview=(NativeGearEntity)NativeGearSnapshot.stage(world,new NativeGearSnapshot.Cell(root,owner.getBlockState(),after),true);var future=NativeGearGeometry.mechanismBoxes(preview,0);boolean clear=NativeGearTargets.excluding(owner,visited,()->{for(var box:future){var bounds=box.deflate(.0001);for(int x=((int)Math.floor(bounds.minX))>>4;x<=((int)Math.floor(bounds.maxX))>>4;x++)for(int z=((int)Math.floor(bounds.minZ))>>4;z<=((int)Math.floor(bounds.maxZ))>>4;z++)if(world.getChunkSource().getChunkNow(x,z)==null)return false;for(var collision:world.getBlockCollisions(null,bounds))if(Shapes.joinIsNotEmpty(Shapes.create(bounds),collision,BooleanOp.AND))return false;}return true;});if(!clear)throw new IllegalArgumentException("The attached landing group would collide; native feet retained");return new NativeGearLandingPlan(sources,new ArrayList<>(targets.values()),after,definition.footKind(),topology.assembly().feet(),roots);
    }
}
